/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic       clk,
    input  logic       reset,
    input  logic       ena,
    output logic       pm,
    output logic [7:0] hh,
    output logic [7:0] mm,
    output logic [7:0] ss
);
    always_ff @(posedge clk) begin
        if (reset) begin
            pm <= 1'b0;
            hh <= 8'h12;
            mm <= 8'h00;
            ss <= 8'h00;
        end else if (ena) begin
            if (ss == 8'h59) begin
                ss <= 8'h00;
                if (mm == 8'h59) begin
                    mm <= 8'h00;
                    if (hh == 8'h11) begin
                        hh <= 8'h12;
                        pm <= ~pm;
                    end else if (hh == 8'h12) begin
                        hh <= 8'h01;
                    end else if (hh[3:0] == 4'd9) begin
                        hh <= 8'h10;
                    end else begin
                        hh <= hh + 8'd1;
                    end
                end else if (mm[3:0] == 4'd9) begin
                    mm <= {mm[7:4] + 4'd1, 4'd0};
                end else begin
                    mm <= mm + 8'd1;
                end
            end else if (ss[3:0] == 4'd9) begin
                ss <= {ss[7:4] + 4'd1, 4'd0};
            end else begin
                ss <= ss + 8'd1;
            end
        end
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic reset = 0;
    logic ena = 0;
    wire pm;
    wire [7:0] hh, mm, ss;
    integer elapsed = 0;
    integer cycles = 0;
    integer hour_expected;
    TopModule dut (.clk(clk), .reset(reset), .ena(ena), .pm(pm), .hh(hh), .mm(mm), .ss(ss));
    always #5 clk = ~clk;
    function automatic [7:0] bcd(input integer value);
        bcd = ((value / 10) << 4) | (value % 10);
    endfunction
    task automatic step(input logic r, input logic e);
        @(negedge clk);
        reset = r;
        ena = e;
        @(posedge clk);
        if (r) elapsed = 0;
        else if (e) elapsed = (elapsed + 1) % 86400;
        #1;
        hour_expected = (elapsed / 3600) % 12;
        if (hour_expected == 0) hour_expected = 12;
        if (hh !== bcd(hour_expected) || mm !== bcd((elapsed / 60) % 60) ||
            ss !== bcd(elapsed % 60) || pm !== (elapsed >= 43200)) begin
            $display("FAIL cycle=%0d elapsed=%0d actual=%b %h:%h:%h", cycles, elapsed, pm, hh, mm, ss);
            $fatal(1);
        end
        cycles = cycles + 1;
    endtask
    initial begin
        step(1, 0);
        step(0, 0);
        step(1, 1);
        for (integer i = 0; i < 172800; i = i + 1) begin
            step(0, 1);
            if (i % 97 == 0) step(0, 0);
        end
        for (integer i = 0; i < 5000; i = i + 1)
            step(i % 811 == 0, i % 7 != 0);
        step(1, 0);
        step(0, 1);
        $display("PASS: %0d checked cycles, two full days plus stalls and resets", cycles);
        $finish;
    end
    initial begin
        #3000000;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
 timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status=$?
cat compile.log
printf '"'compile_exit=%s\\n' \""'$compile_status"
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    simulation_status=$?
    cat simulation.log
    printf '"'simulation_exit=%s\\n' \""'$simulation_status"
fi'

